	"github.com/c360studio/semstreams/component"
	"github.com/c360studio/semstreams/message"
	"github.com/c360studio/semstreams/natsclient"
	"github.com/nats-io/nats.go"
)

const (
	// manifestSubject is the NATS subject for publishing manifest events.
	manifestSubject = "graph.ingest.manifest"

	// querySubject is the NATS subject for request/reply source queries.
	querySubject = "graph.query.sources"

	// summaryQuerySubject is the NATS subject for on-demand summary queries.
	//
	// This is graph.query.SOURCE_summary, not graph.query.summary. The substrate's
	// graph-query serves graph.query.summary with a different payload
	// (graph.SummaryData), and both components run in one SemSource process — so
	// while source-manifest also subscribed there, the reply was a race between
	// two shapes and the subject had no contract. The consumer integration guide
	// always assigned graph.query.summary to graph-query; SemSource was the
	// squatter. Consumers wanting this payload use this subject or
	// GET /source-manifest/summary.
	summaryQuerySubject = "graph.query.sourceSummary"
)

// Component implements the source-manifest processor.
// On startup it publishes a ManifestPayload to the GRAPH stream and
// subscribes to graph.query.sources for on-demand request/reply queries.
// It also aggregates status reports from source components and publishes
// ingestion status and predicate schema to consumers.
type Component struct {
	name   string
	config Config
	// heartbeatFailing: the heartbeat is the liveness signal, so its loss must
	// be visible without logging once per interval (ADR-0011).
	heartbeatFailing degraded.Condition
	client           *natsclient.Client
	logger           *slog.Logger
	// readinessRequest is a test seam for the two bounded index-status probes
	// used by the workbench capability document. Production leaves it nil and
	// reads GRAPH_STATUS through graphStatus instead.
	readinessRequest readinessRequestFunc
	readinessTimeout time.Duration
	// graphStatus reads ADR-083 readiness envelopes from the GRAPH_STATUS KV
	// bucket. It replaces the removed graph.index.query.status request/reply.
	graphStatus *graphstatus.Reader

	// Manifest query
	querySub     *natsclient.Subscription
	responseData []byte // pre-marshaled manifest for HTTP and NATS responses
	// manifestMu guards responseData and the underlying sources slice
	// (config.Sources is stable post-Start, but the canonical "what's
	// configured" list is mutated by ingest Add/Remove).
	manifestMu      sync.RWMutex
	manifestSources []ManifestSource

	// Status aggregation
	aggregator     *statusAggregator
	statusSub      *natsclient.Subscription
	statusQuerySub *natsclient.Subscription
	statusData     []byte // pre-marshaled latest status for HTTP and NATS
	statusMu       sync.RWMutex
	seedComplete   bool
	// removedSources guards against in-flight periodic reports from
	// deregistered components resurrecting phantom status entries. Cleared
	// per-instance on re-add. Guarded by statusMu.
	removedSources map[string]struct{}

	// Predicate schema
	predicatesQuerySub *natsclient.Subscription
	predicatesData     []byte // pre-marshaled predicate schema for HTTP and NATS

	// Summary query
	summaryQuerySub *natsclient.Subscription

	// Ingest API (graph.ingest.add/remove + HTTP POST/DELETE/GET /sources).
	// ingestCfg is nil until RegisterIngestHandlers runs (host wires it after
	// Start); the HTTP façade handlers read it at request time and 503 while nil.
	// Guarded by c.mu.
	ingestSubs []*natsclient.Subscription
	ingestCfg  *IngestHandlerConfig

	// Background goroutine cancellation
	cancelFuncs []context.CancelFunc

	running   bool
	startTime time.Time
	mu        sync.RWMutex
}

// NewComponent creates a new source-manifest component.
func NewComponent(rawConfig json.RawMessage, deps component.Dependencies) (component.Discoverable, error) {
	config := DefaultConfig()
	if err := json.Unmarshal(rawConfig, &config); err != nil {
		return nil, fmt.Errorf("failed to unmarshal config: %w", err)
	}
	if err := config.Validate(); err != nil {
		return nil, fmt.Errorf("invalid config: %w", err)
	}

	return &Component{
		name:        "source-manifest",
		config:      config,
		client:      deps.NATSClient,
		logger:      deps.GetLogger(),
		graphStatus: graphstatus.New(deps.NATSClient),
	}, nil
}

// Initialize prepares the component (no-op).
func (c *Component) Initialize() error { return nil }

// Start publishes the manifest and predicate schema, then begins
// listening for source status reports and serving queries.
func (c *Component) Start(ctx context.Context) error {
	c.mu.Lock()
	if c.running {
		c.mu.Unlock()
		return fmt.Errorf("component already running")
	}
	c.mu.Unlock()

	if err := c.startManifest(ctx); err != nil {
		return err
	}
	if err := c.startPredicateSchema(ctx); err != nil {
		return err
	}
	if err := c.startStatusAggregation(ctx); err != nil {
		return err
	}

	c.mu.Lock()
	c.running = true
	c.startTime = time.Now()
	c.mu.Unlock()

	return nil
}

// startManifest publishes the manifest and sets up query handlers.
func (c *Component) startManifest(ctx context.Context) error {
	c.manifestMu.Lock()
	c.manifestSources = append([]ManifestSource(nil), c.config.Sources...)
	c.manifestMu.Unlock()

	if err := c.publishManifest(ctx); err != nil {
		return err
	}

